const run = $('Run Greenhouse Edit Feed Actor').first().json;
const summary = $json;
if (!run || typeof run.id !== 'string' || !run.id) throw new Error('Actor response is missing a run ID; no dataset or table writes allowed');
if (run.status !== 'SUCCEEDED') throw new Error(`Actor run is not SUCCEEDED (status=${run.status ?? 'unknown'}); no rows changed`);
if (summary.source_run_id !== run.id) throw new Error('SUMMARY source_run_id does not match the completed Actor run; no rows changed');
if (summary.allBoardsCompleted !== true || summary.datasetVerified !== true) throw new Error('Actor SUMMARY completion or dataset verification failed; inspect the run before retrying; no rows changed');
if (!Number.isInteger(summary.requestedBoards) || summary.requestedBoards < 1 || summary.completedBoards !== summary.requestedBoards) throw new Error('Actor SUMMARY board manifest is incomplete; no rows changed');
if (!Array.isArray(summary.manifest) || summary.manifest.length !== summary.requestedBoards || summary.manifest.some((board) => board.committed !== true || typeof board.board !== 'string' || !board.board)) throw new Error('Actor SUMMARY contains an invalid or uncommitted board; no rows changed');
const manifestBoards = summary.manifest.map((board) => board.board);
if (new Set(manifestBoards).size !== manifestBoards.length) throw new Error('Actor SUMMARY has duplicate board entries; no rows changed');
if (!Number.isInteger(summary.eventRows) || summary.eventRows < 0) throw new Error('Actor SUMMARY eventRows is invalid; no rows changed');
if (typeof run.defaultDatasetId !== 'string' || !run.defaultDatasetId || typeof run.defaultKeyValueStoreId !== 'string' || !run.defaultKeyValueStoreId) throw new Error('Actor run is missing dataset or key-value store IDs; no rows changed');
return [{ json: { run_id: run.id, default_dataset_id: run.defaultDatasetId, expected_event_rows: summary.eventRows, requested_boards: summary.requestedBoards, completed_boards: summary.completedBoards, manifest_boards: manifestBoards, allBoardsCompleted: true, datasetVerified: true, source_run_id: summary.source_run_id } }];

const run = $('Run Greenhouse Edit Feed Actor').first().json;
const gate = $('Validate completed Actor SUMMARY').first().json;
const sourceItems = $input.all();
const incoming = [];
for (const item of sourceItems) {
  if (Array.isArray(item.json)) incoming.push(...item.json);
  else incoming.push(item.json);
}
if (incoming.length !== gate.expected_event_rows) throw new Error(`Dataset readback count ${incoming.length} does not match verified SUMMARY.eventRows ${gate.expected_event_rows}; no rows changed`);
const seenEventIds = new Set();
const latestByKey = new Map();
for (const event of incoming) {
  if (!event || typeof event !== 'object' || typeof event.event !== 'string') throw new Error('Dataset contains a malformed event; no rows changed');
  if (event.source_run_id !== run.id) throw new Error('Dataset event source_run_id does not match this Actor run; no rows changed');
  if (event.event === 'board_error') throw new Error('Dataset contains a board_error despite a complete SUMMARY; no rows changed');
  if (event.event === 'scope_reset' || event.event === 'timestamp_only') continue;
  if (typeof event.board !== 'string' || !gate.manifest_boards.includes(event.board)) throw new Error('Dataset event board is outside the completed Actor manifest; no rows changed');
  if (!Number.isInteger(event.post_id) || event.post_id <= 0) throw new Error('Job event requires integer post_id');
  if (typeof event.event_id !== 'string' || !event.event_id) throw new Error('Actor event_id is required for replay deduplication');
  if (seenEventIds.has(event.event_id)) throw new Error('Dataset contains duplicate event_id despite datasetVerified; no rows changed');
  seenEventIds.add(event.event_id);
  const key = JSON.stringify([event.board, event.post_id]);
  const post = event.after || event.before;
  if (!post || typeof post !== 'object') throw new Error('Job event requires before or after data');
  const description = typeof post.description_text === 'string' ? post.description_text : '';
  const descriptionHash = typeof post.description_hash === 'string' ? post.description_hash : '';
  if (description && (!/^[a-f0-9]{64}$/.test(descriptionHash))) throw new Error('Description hash is missing or invalid');
  let visibility = 'visible';
  if (event.event === 'missing_candidate') visibility = 'uncertain';
  if (event.event === 'closed') visibility = 'hidden';
  const fields = {
    display_id: key, board: event.board, post_id: event.post_id, event: event.event, visibility,
    title: typeof post.title === 'string' ? post.title : '',
    location: typeof post.location === 'string' ? post.location : '',
    url: typeof post.url === 'string' ? post.url : '',
    description_text: description, description_hash: descriptionHash,
    updated_at: typeof post.updated_at === 'string' ? post.updated_at : '',
    observed_at: typeof event.observed_at === 'string' ? event.observed_at : '',
    event_id: event.event_id, source_run_id: event.source_run_id,
    changed_fields: Array.isArray(event.changed_fields) ? event.changed_fields.join(',') : ''
  };
  latestByKey.set(key, fields);
}
return [...latestByKey.values()].map((json) => ({ json }));
